import { Factory, Hammer, Scale, Users, Landmark, TrendingUp } from "lucide-react";
import PageHero from "@/components/ui/PageHero";
import Section from "@/components/ui/Section";
import SectionHeading from "@/components/ui/SectionHeading";
import FeatureGrid from "@/components/ui/FeatureGrid";
import CtaBand from "@/components/ui/CtaBand";
import Reveal from "@/components/ui/Reveal";
import CountUp from "@/components/ui/CountUp";
import Querverweise from "@/components/Reusable/Querverweise";
import { rechnerMetadata } from "@/components/Rechner/RechnerSeite";
import GruppenGrafik from "@/components/Unternehmen/GruppenGrafik";
import Zeitleiste from "@/components/Unternehmen/Zeitleiste";
import { MEILENSTEINE, PERSONEN, WERTE } from "@/components/Unternehmen/daten";
import { GESELLSCHAFT, KENNZAHLEN, SITE, abs } from "@/data/site";

const PFAD = "/unternehmen";

export const metadata = rechnerMetadata({
  pfad: PFAD,
  title: "Über ÖkoInvest – Teil der ÖKOVOLT Gruppe | ÖkoInvest",
  description:
    "ÖkoInvest GmbH aus Ostermiething: Projektentwicklung für Freiflächen-PV, Agri-PV und Speicher in der ÖKOVOLT Gruppe, die seit 2012 eigene Solarparks betreibt.",
  keywords: ["ÖkoInvest GmbH", "ÖKOVOLT Gruppe", "Projektentwickler Photovoltaik", "Ostermiething", "Solarpark Entwickler Österreich Deutschland"],
});

const ICONS = { Factory, Scale, Hammer, Users };

const QUERVERWEISE = [
  { href: "/prozess", titel: "Projektprozess", text: "Von der Anfrage bis zum Betrieb – Schritte, Dauer, Dokumente." },
  { href: "/projektboerse", titel: "Projektbörse", text: "Projekte in allen Phasen für Investoren im DACH-Raum." },
  { href: "/kontakt", titel: "Kontakt", text: "Anfrage an das Projektteam in Ostermiething." },
];

const schema = {
  "@context": "https://schema.org",
  "@type": "AboutPage",
  "@id": `${abs(PFAD)}/#webpage`,
  url: abs(PFAD),
  name: "Über ÖkoInvest",
  isPartOf: { "@id": `${abs("/")}/#website` },
  mainEntity: {
    "@type": "Organization",
    "@id": `${abs("/")}/#organization`,
    name: SITE.name,
    legalName: GESELLSCHAFT.name,
    url: abs("/"),
    foundingDate: "2020-09-10",
    description: GESELLSCHAFT.gegenstand,
    address: {
      "@type": "PostalAddress",
      streetAddress: GESELLSCHAFT.sitz,
      postalCode: GESELLSCHAFT.plz,
      addressLocality: GESELLSCHAFT.ort,
      addressCountry: "AT",
    },
    identifier: { "@type": "PropertyValue", propertyID: "Firmenbuchnummer", value: GESELLSCHAFT.register },
    employee: GESELLSCHAFT.geschaeftsfuehrung.map((n) => ({ "@type": "Person", name: n, jobTitle: "Geschäftsführer" })),
    parentOrganization: { "@type": "Organization", name: SITE.gruppe, url: SITE.gruppeUrl },
    subOrganization: GESELLSCHAFT.beteiligungen.map((b) => ({ "@type": "Organization", name: b.name })),
    areaServed: KENNZAHLEN.maerkte.map((m) => ({ "@type": "Country", name: m })),
  },
};

export default function UnternehmenPage() {
  const register = [
    ["Firma", GESELLSCHAFT.name],
    ["Sitz", `${GESELLSCHAFT.sitz}, ${GESELLSCHAFT.plz} ${GESELLSCHAFT.ort}, ${GESELLSCHAFT.land}`],
    ["Firmenbuch", GESELLSCHAFT.register],
    ["Firmenbuchgericht", GESELLSCHAFT.gericht],
    ["Eingetragen", GESELLSCHAFT.eingetragen],
    ["Geschäftsführung", GESELLSCHAFT.geschaeftsfuehrung.join(", ")],
    ["UID-Nummer", GESELLSCHAFT.uid],
    ["Unternehmensgegenstand", GESELLSCHAFT.gegenstand],
  ].filter(([, v]) => v);

  return (
    <div>
      <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(schema) }} />

      <PageHero
        breadcrumbs={[{ name: "Über ÖkoInvest" }]}
        eyebrow="Unternehmen · Teil der ÖKOVOLT Gruppe"
        title={
          <>
            Wir entwickeln Kraftwerke, <span className="ov-text-gradient">die wir selbst betreiben würden.</span>
          </>
        }
        lead="ÖkoInvest ist die Projektgesellschaft der ÖKOVOLT Gruppe. Aus Ostermiething entwickeln wir Solarparks, Agri-PV, Solarcarports und Speicher im DACH-Raum – mit der Erfahrung einer Gruppe, die seit 2010 Solaranlagen baut und seit 2012 eigene Parks betreibt."
        image={{ src: "/img/firmensitz.jpg", alt: "Firmensitz der ÖKOVOLT Gruppe" }}
        stats={[
          { value: 15, suffix: "+", label: "Jahre Solargeschäft der Gruppe" },
          { value: KENNZAHLEN.maerkte.length, label: "Märkte: DE, AT, CH" },
          { value: KENNZAHLEN.entwicklungMwProJahr, suffix: " MWp", label: "neu in Entwicklung pro Jahr" },
        ]}
      />

      {/* Rolle in der Gruppe */}
      <Section tone="white" space="lg">
        <div className="grid items-start gap-12 lg:grid-cols-[0.9fr_1.1fr] lg:gap-16">
          <div>
            <SectionHeading
              eyebrow="Rolle in der Gruppe"
              title="Die Gruppe baut auf Dächern. Wir entwickeln auf der Fläche."
              lead="Die ÖKOVOLT-Gesellschaften in Deutschland und Österreich planen und bauen Photovoltaik und Speicher für Gewerbe, Industrie, Kommunen und Landwirtschaft. ÖkoInvest übernimmt den Teil, der Jahre dauert: Flächen sichern, Planungsrecht und Netzanschluss erreichen, Projekte finanzieren und vermarkten."
            />
            <ul className="mt-8 space-y-3 text-[15.5px] leading-relaxed text-ink-700">
              {[
                "Projektentwicklung für Freiflächen-PV, Agri-PV, Solarcarports und Großspeicher",
                "Contracting und Stromlieferverträge (PPA)",
                "Projektbörse für Investoren und Projektanbieter",
                "Virtuelles Kraftwerk und Reststrom-Pool für die Unternehmenskunden der Gruppe",
              ].map((t) => (
                <li key={t} className="flex gap-3">
                  <span aria-hidden="true" className="mt-2.5 h-1.5 w-1.5 shrink-0 rounded-full bg-ov-500" />
                  {t}
                </li>
              ))}
            </ul>
          </div>
          <Reveal dir="right">
            <GruppenGrafik />
          </Reveal>
        </div>
      </Section>

      {/* Geschichte */}
      <Section tone="navy" space="lg" className="overflow-hidden">
        <div aria-hidden="true" className="ov-grid-bg absolute inset-0" />
        <div aria-hidden="true" className="absolute -left-40 top-40 h-[460px] w-[460px] rounded-full bg-ov-500/20 blur-[130px]" />
        <div className="relative">
          <SectionHeading
            dark
            align="center"
            eyebrow="Geschichte"
            title="Von der ersten Anlage zum eigenen Solarpark"
            lead="Was uns unterscheidet, ist nicht die Planung – sondern dass die Gruppe ihre frühen Solarparks bis heute selbst betreibt."
            className="mb-14 md:mb-20"
          />
          <Zeitleiste items={MEILENSTEINE} />
        </div>
      </Section>

      {/* Geschäftsführung */}
      <Section tone="white" space="lg">
        <SectionHeading eyebrow="Geschäftsführung" title="Die Menschen hinter ÖkoInvest" className="mb-10 md:mb-14" />
        <div className="grid gap-5 md:grid-cols-2">
          {PERSONEN.map((p, i) => (
            <Reveal key={p.name} delay={i * 80} className="flex flex-col gap-5 rounded-3xl bg-sand-50 p-6 ring-1 ring-ink-200/70 sm:flex-row sm:items-start md:p-8">
              <span
                aria-hidden="true"
                className="flex h-24 w-24 shrink-0 items-center justify-center rounded-3xl bg-gradient-to-br from-ov-100 to-sand-100 font-display text-[34px] font-extrabold text-ov-600 ring-1 ring-ov-200"
              >
                {p.initialen}
              </span>
              <div>
                <h3 className="font-display text-[22px] font-bold leading-tight text-ink-900">{p.name}</h3>
                <p className="mt-1 text-[14.5px] font-semibold text-ov-700">{p.rolle}</p>
                <p className="mt-3 text-[15.5px] leading-relaxed text-ink-600">{p.text}</p>
              </div>
            </Reveal>
          ))}
        </div>
      </Section>

      {/* Pipeline */}
      <Section tone="green" space="lg">
        <div className="grid items-center gap-10 lg:grid-cols-[auto_1fr] lg:gap-16">
          <Reveal dir="scale" className="rounded-[2rem] bg-white p-8 text-center shadow-xl ring-1 ring-ov-200 md:p-10">
            <TrendingUp aria-hidden="true" className="mx-auto h-8 w-8 text-ov-600" />
            <p className="mt-4 font-display text-[clamp(3rem,2.4rem+2.6vw,4.5rem)] font-extrabold leading-none tracking-tight text-ink-900">
              <CountUp value={KENNZAHLEN.entwicklungMwProJahr} prefix="~" suffix=" MWp" />
            </p>
            <p className="mt-3 text-[15px] text-ink-600">gehen pro Jahr neu in die Entwicklung</p>
          </Reveal>
          <SectionHeading
            eyebrow="Pipeline"
            title="Ehrlich über Zeit"
            lead="Wir nehmen jedes Jahr rund 50 MWp neu in die Entwicklung – Flächen, die gesichert und geprüft werden. Bis daraus baureife Projekte werden, vergehen in der Regel mehrere Jahre: Planungsrecht, Netzanschluss und Vermarktung brauchen Zeit, und nicht jedes Projekt erreicht die Baureife. Deshalb nennen wir keine Fertigstellungszahlen, die wir nicht belegen können."
          />
        </div>
      </Section>

      {/* Werte */}
      <Section tone="white" space="lg">
        <SectionHeading eyebrow="Werte" title="Wofür wir stehen" className="mb-10 md:mb-14" />
        <FeatureGrid items={WERTE.map((w) => ({ ...w, icon: ICONS[w.icon] }))} cols={4} />
      </Section>

      {/* Register */}
      <Section tone="sand" space="lg" id="register" className="scroll-mt-24">
        <div className="grid gap-10 lg:grid-cols-[0.8fr_1.2fr] lg:gap-16">
          <SectionHeading
            eyebrow="Registerangaben"
            title="Gesellschaft & Beteiligungen"
            lead="Alle Angaben sind im österreichischen Firmenbuch öffentlich abrufbar."
          >
            <p className="mt-6 flex items-center gap-2 text-[14px] text-ink-500">
              <Landmark aria-hidden="true" className="h-4 w-4 text-ov-600" />
              Weitere Pflichtangaben im Impressum
            </p>
          </SectionHeading>
          <div className="space-y-5">
            <Reveal className="rounded-3xl bg-white p-6 ring-1 ring-ink-200/70 md:p-8">
              <dl className="divide-y divide-ink-200/70">
                {register.map(([k, v]) => (
                  <div key={k} className="grid gap-1 py-3 text-[15px] sm:grid-cols-[180px_1fr] sm:gap-4">
                    <dt className="text-ink-500">{k}</dt>
                    <dd className="font-medium text-ink-900">{v}</dd>
                  </div>
                ))}
              </dl>
            </Reveal>
            <div className="grid gap-4 sm:grid-cols-2">
              {GESELLSCHAFT.beteiligungen.map((b, i) => (
                <Reveal key={b.name} delay={i * 70} className="rounded-3xl bg-white p-6 ring-1 ring-ink-200/70">
                  <p className="text-[12.5px] font-semibold uppercase tracking-[0.12em] text-ov-700">Beteiligung · {b.anteil}</p>
                  <h3 className="mt-2 font-display text-[18px] font-bold text-ink-900">{b.name}</h3>
                  <p className="mt-1 text-[14px] text-ink-500">{b.register}</p>
                  <p className="mt-3 text-[15px] leading-relaxed text-ink-600">{b.text}</p>
                </Reveal>
              ))}
            </div>
          </div>
        </div>
      </Section>

      <Querverweise items={QUERVERWEISE} />
      <CtaBand
        eyebrow="Zusammenarbeiten"
        title="Fläche, Projekt, Kapital oder Strombedarf? Sprechen wir darüber."
        primary={{ label: "Kontakt aufnehmen", href: "/kontakt" }}
        secondary={{ label: "Projektprozess ansehen", href: "/prozess" }}
      />
    </div>
  );
}
import { Building2, Factory, Hammer, Sun, Zap } from "lucide-react";
import { GESELLSCHAFT } from "@/data/site";
import { cn } from "@/components/ui/cn";

/**
 * Struktur der Gruppe aus Sicht von ÖkoInvest – bewusst ohne
 * Beteiligungsquoten an ÖkoInvest selbst (nur belegte Angaben).
 */
export default function GruppenGrafik() {
  return (
    <figure className="rounded-[2rem] bg-white p-5 shadow-xl ring-1 ring-ink-200/70 sm:p-8">
      <figcaption className="sr-only">Einordnung der ÖkoInvest GmbH in die ÖKOVOLT Gruppe mit ihren Beteiligungen</figcaption>

      <Knoten dunkel icon={Building2} titel="ÖKOVOLT Gruppe" text="Familiengeführt, seit 2010 im Solargeschäft" />
      <Linie />
      <div className="grid gap-2.5">
        <Knoten icon={Factory} titel="ÖKOVOLT GmbH Solartechnik" text="Muttergesellschaft, Türkheim (DE) – PV und Speicher für Gewerbe" land="DE" />
        <Knoten icon={Factory} titel="ÖKOVOLT Solartechnik GmbH" text="Schwestergesellschaft, Ostermiething (AT)" land="AT" />
        <Knoten icon={Hammer} titel="Deutsche Solar & Rammtechnik GmbH" text="Fundamente für Freiflächenanlagen" land="DE" />
      </div>
      <Linie />
      <Knoten gruen icon={Sun} titel={GESELLSCHAFT.name} text="Projektentwicklung Freifläche, Agri-PV, Carports, Speicher · Projektbörse · virtuelles Kraftwerk" land="AT" />
      <Linie />
      <div className="grid gap-3 sm:grid-cols-2">
        {GESELLSCHAFT.beteiligungen.map((b) => (
          <Knoten key={b.name} icon={Zap} titel={b.name} text={b.text} anteil={b.anteil} />
        ))}
      </div>
    </figure>
  );
}

function Linie() {
  return <div aria-hidden="true" className="mx-auto h-6 w-0.5 bg-gradient-to-b from-ov-300 to-ov-500" />;
}

function Knoten({ icon: Icon, titel, text, land, anteil, dunkel, gruen }) {
  return (
    <div
      className={cn(
        "relative flex items-start gap-3 rounded-2xl p-4",
        dunkel ? "bg-navy-950 text-white" : gruen ? "bg-ov-600 text-white shadow-[0_12px_32px_-12px_rgba(102,153,51,0.7)]" : "bg-sand-50 ring-1 ring-ink-200/70"
      )}
    >
      <span className={cn("flex h-10 w-10 shrink-0 items-center justify-center rounded-xl", dunkel ? "bg-white/10 text-ov-300" : gruen ? "bg-white/15 text-white" : "bg-white text-ov-600 ring-1 ring-ink-200")}>
        <Icon aria-hidden="true" className="h-5 w-5" />
      </span>
      <div className="min-w-0">
        <p className={cn("font-display text-[15.5px] font-bold leading-snug", dunkel || gruen ? "text-white" : "text-ink-900")}>
          {titel}
          {land && <span className={cn("ml-2 rounded px-1.5 py-0.5 align-middle text-[10.5px] font-bold", dunkel || gruen ? "bg-white/15 text-white" : "bg-ink-100 text-ink-600")}>{land}</span>}
        </p>
        <p className={cn("mt-0.5 text-[13px] leading-snug", dunkel ? "text-white/60" : gruen ? "text-white/85" : "text-ink-600")}>{text}</p>
        {anteil && <p className="mt-1.5 text-[12.5px] font-semibold text-ov-700">Anteil ÖkoInvest: {anteil}</p>}
      </div>
    </div>
  );
}
import Reveal from "@/components/ui/Reveal";
import { cn } from "@/components/ui/cn";

/**
 * Chronologie auf dunklem Grund. Mobil: Linie links; ab md: abwechselnd
 * links/rechts der Mittellinie, leicht versetzt.
 * items: [{ jahr, titel, text, hervorgehoben? }]
 */
export default function Zeitleiste({ items = [] }) {
  return (
    <ol className="relative mx-auto max-w-5xl">
      <div aria-hidden="true" className="absolute bottom-6 left-[19px] top-6 w-px bg-gradient-to-b from-ov-400 via-white/20 to-ov-400 md:left-1/2" />
      {items.map((e, i) => {
        const rechts = i % 2 === 1;
        return (
          <Reveal
            as="li"
            key={e.jahr}
            delay={i * 50}
            dir={rechts ? "right" : "left"}
            className={cn("relative pb-10 pl-14 last:pb-0 md:w-1/2 md:pb-4 md:pl-0", rechts ? "md:ml-auto md:pl-12" : "md:pr-12 md:text-right", i > 0 && "md:-mt-16")}
          >
            <span
              aria-hidden="true"
              className={cn(
                "absolute left-0 top-1 flex h-10 w-10 items-center justify-center rounded-full",
                rechts ? "md:-left-5" : "md:left-auto md:-right-5",
                e.hervorgehoben ? "bg-ov-500 shadow-[0_0_0_6px_rgba(102,153,51,0.25)]" : "bg-navy-950 ring-2 ring-ov-400"
              )}
            >
              <span className={cn("h-2.5 w-2.5 rounded-full", e.hervorgehoben ? "bg-white" : "bg-ov-400")} />
            </span>
            <p className="font-display text-[clamp(1.6rem,1.2rem+1.3vw,2.4rem)] font-extrabold leading-none tracking-tight text-white">{e.jahr}</p>
            <div className={cn("ov-glass mt-4 rounded-3xl p-5 text-left md:p-6", e.hervorgehoben && "ring-1 ring-ov-400/40")}>
              <h3 className="font-display text-[17px] font-bold text-white">{e.titel}</h3>
              <p className="mt-1.5 text-[15px] leading-relaxed text-white/65">{e.text}</p>
            </div>
          </Reveal>
        );
      })}
    </ol>
  );
}
// Inhalte der Seite /unternehmen.
// QUELLEN: Registerangaben aus src/data/site.js (Firmenbuch AT); Gruppen-
// geschichte aus der Ökovolt-DE-Website (src/data/unternehmen.js, dort mit
// Register- und Jahresabschlussangaben belegt). Keine eigenen Kennzahlen
// über ÖkoInvest außer der Entwicklungs-Pipeline (Vorgabe Geschäftsführung).

import { GESELLSCHAFT, KENNZAHLEN } from "@/data/site";

export const MEILENSTEINE = [
  {
    jahr: "2010",
    titel: "Der Anfang in Türkheim",
    text: "Andreas Wegscheider und Susanne Messmer gründen die ÖKOVOLT GmbH, die bis heute ihren Sitz in Türkheim im Unterallgäu hat – mit eigener Montagegesellschaft. Planung, Bau und Inbetriebnahme kommen von Beginn an aus einer Hand.",
    hervorgehoben: true,
  },
  {
    jahr: "2012",
    titel: "Vom Dach aufs Feld",
    text: "Die Gründer bauen die ersten Solarparks – und betreiben sie selbst, jeweils über eine eigene Betreibergesellschaft, etwa in Artern und Tilleda. Für die Fundamente entsteht die Deutsche Solar & Rammtechnik GmbH. Im selben Jahr wird die österreichische Schwestergesellschaft gegründet.",
  },
  {
    jahr: "2013",
    titel: "Solarpark vor der Haustür",
    text: "Mit dem Solarpark in Irsingen, einem Ortsteil von Türkheim, entsteht ein Park direkt am Firmensitz.",
  },
  {
    jahr: "2020",
    titel: "Gründung der ÖkoInvest GmbH",
    text: `Am ${GESELLSCHAFT.eingetragen} wird die ${GESELLSCHAFT.name} in ${GESELLSCHAFT.ort} ins Firmenbuch eingetragen – als Projektgesellschaft der Gruppe für Freiflächen-PV, Agri-PV, Contracting und Stromlieferverträge.`,
    hervorgehoben: true,
  },
  {
    jahr: "2021",
    titel: "Neu aufgestellt",
    text: "Die Gruppe ordnet sich neu: Die Solarparks der Gründer werden in einer Beteiligungsgesellschaft gebündelt, die deutsche ÖKOVOLT konzentriert sich auf Planung und Bau. Die österreichische Schwester errichtet allein in diesem Jahr PV-Anlagen mit 30 MWp.",
  },
  {
    jahr: "2023",
    titel: "Eigene Kraftwerksgesellschaften",
    text: "Mit der GFL – PV-Kraftwerk GmbH entsteht eine hundertprozentige Tochter für den Betrieb von PV-Kraftwerken. Später folgt die HIL PV Kraftwerk GmbH als Gemeinschaftsgesellschaft mit der Prime Energy Solutions GmbH.",
  },
  {
    jahr: "Heute",
    titel: "Plattform für den DACH-Raum",
    text: `Rund ${KENNZAHLEN.entwicklungMwProJahr} MWp gehen jedes Jahr neu in die Entwicklung. Mit Projektbörse, Portal und virtuellem Kraftwerk öffnen wir die Projektentwicklung für Flächeneigentümer, Investoren, Unternehmen und Bürger.`,
    hervorgehoben: true,
  },
];

export const WERTE = [
  { icon: "Factory", title: "Betreiber aus Überzeugung", text: "Die Gruppe betreibt eigene Solarparks seit 2012. Wir entwickeln nur, was wir selbst betreiben würden – mit Erfahrung aus über einem Jahrzehnt Ertrag, Wartung und Direktvermarktung." },
  { icon: "Scale", title: "Ehrliche Zahlen", text: "Spannen statt Versprechen: Unsere Rechner zeigen Annahmen und Quellen offen. Keine Renditezusagen, keine geschönten Zeitpläne." },
  { icon: "Hammer", title: "Alles aus einer Gruppe", text: "Entwicklung, eigene Rammtechnik, Bau und Betrieb liegen in einer Unternehmensgruppe. Das verkürzt Wege und hält Verantwortung an einer Stelle." },
  { icon: "Users", title: "Wertschöpfung vor Ort", text: "Pacht für Eigentümer, Einnahmen für Gemeinden, Beteiligung für Bürger und Landwirte: Ein Solarpark soll der Region nützen, in der er steht." },
];

export const PERSONEN = [
  {
    initialen: "AW",
    name: "Andreas Wegscheider",
    rolle: "Geschäftsführer",
    text: "Gründer der ÖKOVOLT Gruppe und Pionier der Photovoltaik im DACH-Raum. Er hat Anlagen geplant und montiert, als Module noch ein Vielfaches kosteten – und mit den ersten eigenen Solarparks ab 2012 den Schritt vom Dach auf die Freifläche gemacht.",
  },
  {
    initialen: "MT",
    name: "Manuel Thaler",
    rolle: "Geschäftsführer",
    text: "Seit mehr als zehn Jahren Teil der ÖKOVOLT-Familie und in der Gruppe für den Vertrieb verantwortlich. Er kennt Netzbetreiber, Förderlandschaft und die Anforderungen von Gewerbekunden aus der täglichen Projektpraxis.",
  },
];

// Hero der Seite /energiegemeinschaften/software
// Aufbau: Hinweis-Pill (ElWG) → Headline → Lead → Handlungen → Versprechen (2×2) | Produktbühne (HeroKomposition)
import { ArrowRight, Calculator, Check } from "lucide-react";
import Breadcrumbs from "@/components/ui/Breadcrumbs";
import Button from "@/components/ui/Button";
import { cn } from "@/components/ui/cn";
import { HeroKomposition } from "@/components/Portal/EG/Produkt/Mockups";

/** Kurzversprechen – mobil die ersten zwei, ab sm alle vier */
const HERO_CHIPS = [
  "Geführte Zustimmung beim Netzbetreiber",
  "Mehrfachteilnahme bis fünf Gemeinschaften",
  "Gründung, Wechsel und Betrieb",
  "EDA-Rolle bleibt bei der Gemeinschaft",
];

export default function Hero() {
  return (
    <section data-abschnitt="hero" aria-labelledby="hero-titel" className="ov-verlauf-nacht ov-noise relative isolate overflow-hidden text-white">
