/* Grüner Verlaufstext für Schlüsselwörter in Headlines */
.ov-text-gradient {
  background: linear-gradient(100deg, #8cba58 0%, #669933 45%, #3f7a2a 100%);
  -webkit-background-clip: text;
  background-clip: text;
