}
.ov-range::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 26px;
  height: 26px;
  border-radius: 9999px;
  background: #fff;
  border: 2px solid #669933;
  box-shadow: 0 2px 10px rgba(21, 26, 36, 0.2);
  cursor: grab;
  transition: transform 150ms;
}
.ov-range::-webkit-slider-thumb:active { transform: scale(1.12); cursor: grabbing; }
.ov-range::-moz-range-thumb {
  width: 24px;
  height: 24px;
  border-radius: 9999px;
  background: #fff;
  border: 2px solid #669933;
  box-shadow: 0 2px 10px rgba(21, 26, 36, 0.2);
  cursor: grab;
}
.ov-range:focus-visible {
  box-shadow: 0 0 0 4px rgba(102, 153, 51, 0.3);
  /* sichtbarer Fokusring (WCAG 2.4.7) – überschreibt `outline: none` oben */
  outline: 3px solid var(--color-ov-600);
