  "@context": "https://schema.org",
  "@type": "FAQPage",
  "@id": `${abs(PFAD)}/#faq`,
  url: abs(PFAD),
  mainEntity: alle.map((it) => ({
    "@type": "Question",
    name: it.q,
    acceptedAnswer: { "@type": "Answer", text: typeof it.a === "string" ? it.a : it.aText || "" },
  })),
};

