        breadcrumbs={[{ name: "Wissen", href: "/ratgeber" }, { name: "FAQ" }]}
        eyebrow="Häufige Fragen"
        title={
          <>
            Kurz gefragt, <span className="ov-text-gradient-light">klar beantwortet.</span>
          </>
